package network.velora.mobile;
import android.app.Activity;import android.os.Bundle;import android.content.*;import android.webkit.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;
public class IsolatedPageActivity extends Activity {
 static final Map<String,JSONArray> bundles=new java.util.concurrent.ConcurrentHashMap<>();private static final Set<IsolatedPageActivity> active=java.util.Collections.newSetFromMap(new java.util.concurrent.ConcurrentHashMap<IsolatedPageActivity,Boolean>()); public static void networkChanged(boolean enabled,boolean nexora){for(IsolatedPageActivity page:active)if(page.bundleId==null&&(!enabled||!nexora))page.runOnUiThread(()->{if(page.web!=null)page.web.stopLoading();page.finish();});} private WebView web;private String bundleId;private String site;
 public void onCreate(Bundle state){super.onCreate(state);active.add(this);bundleId=getIntent().getStringExtra("bundle");site=getIntent().getStringExtra("site");LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Button close=new Button(this);close.setText(site==null?"Close app preview":"Close · "+site);close.setOnClickListener(v->finish());root.addView(close,new LinearLayout.LayoutParams(-1,-2));web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(false);CookieManager.getInstance().setAcceptCookie(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setSupportMultipleWindows(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setWebChromeClient(new WebChromeClient());web.setDownloadListener((u,a,b,c,d)->{});web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(bundleId!=null)return !url.startsWith("https://velora.app/"+bundleId+"/");if(url.startsWith("nexora://")){String domain=request.getUrl().getHost();if(domain!=null&&domain.matches("[a-z0-9][a-z0-9-]*\\.(nex|vnt|zen|orb|kiv)")){site=domain;view.loadUrl("https://nexora-api-production-90da.up.railway.app/v1/assets/"+domain+request.getUrl().getPath());}return true;}return !url.startsWith("https://nexora-api-production-90da.up.railway.app/v1/assets/");}public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){try{String url=request.getUrl().toString();if(bundleId!=null){String prefix="https://velora.app/"+bundleId+"/";if(!url.startsWith(prefix))return empty();String wanted=url.substring(prefix.length()).split("[?#]")[0];if(wanted.contains("..")||wanted.contains("\\"))return empty();JSONArray files=bundles.get(bundleId);if(files==null)return empty();for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(f.getString("path").equals(wanted)){String ext=wanted.substring(wanted.lastIndexOf('.')+1);String type=ext.equals("html")?"text/html":ext.equals("css")?"text/css":ext.equals("js")?"text/javascript":ext.equals("png")?"image/png":ext.equals("jpg")||ext.equals("jpeg")?"image/jpeg":ext.equals("svg")?"image/svg+xml":"application/octet-stream";byte[] bytes=android.util.Base64.decode(f.getString("data"),android.util.Base64.DEFAULT);return new WebResourceResponse(type,"UTF-8",new ByteArrayInputStream(bytes));}}return empty();}if(!url.startsWith("https://nexora-api-production-90da.up.railway.app/v1/assets/")||!request.getMethod().equals("GET"))return empty();JSONObject network=new JSONObject(getSharedPreferences("velora-native",0).getString("network","{}"));if(!network.optBoolean("online")||!network.getJSONObject("features").optBoolean("nexora",true))return empty();}catch(Exception e){return empty();}return null;}});web.loadUrl(bundleId==null?"https://nexora-api-production-90da.up.railway.app/v1/assets/"+site+"/index.html":"https://velora.app/"+bundleId+"/index.html");}
 private WebResourceResponse empty(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}
 protected void onDestroy(){active.remove(this);if(web!=null){web.stopLoading();web.destroy();}if(bundleId!=null)bundles.remove(bundleId);super.onDestroy();}
}
